export async function searchMemoryHttp(
	query: string,
	opts: {
		port: number;
		collection?: string;
		collections?: string[];
		pageSize?: number;
		timeoutMs?: number;
		/**
		 * Include vec (semantic) embedding search alongside lex. Default: true.
		 * The daemon keeps the embedding model in memory after first load
		 * (~2s cold, then ~2s per unique query; repeated queries cached ~37ms).
		 * Set false for strict latency budgets.
		 */
		includeVec?: boolean;
		/**
		 * Re-score merged lex+vec hits with a cross-encoder for higher precision.
		 * Default: true. Warm cost ~270ms (model stays in daemon memory).
		 * Improves relevance ordering and reduces noise injected into context,
		 * saving tokens in the active-recall haiku call.
		 */
		rerank?: boolean;
		candidateLimit?: number;
		extraQueries?: string[];
	},
): Promise<SearchResult> {
	// Two-pass: when extraQueries is set, run the main query plus each sub-query
	// in parallel and merge by permalink (highest score wins). Generic mechanism
	// for multi-topic prompts; caller decides decomposition.
	if (opts.extraQueries && opts.extraQueries.length > 0) {
		const { extraQueries, ...base } = opts;
		const all = await Promise.all(
			[query, ...extraQueries].map((q) => searchMemoryHttp(q, base)),
		);
		const best = new Map<string, SearchHit>();
		let anyTimedOut = false;
		for (const r of all) {
			if (r.timedOut) anyTimedOut = true;
			for (const h of r.results) {
				const key = h.permalink ?? `${h.title}${h.file_path ?? ""}`;
				const prev = best.get(key);
				if (!prev || (h.score ?? 0) > (prev.score ?? 0)) best.set(key, h);
			}
		}
		const merged = [...best.values()].sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
		return { results: merged.slice(0, opts.pageSize ?? 5), timedOut: anyTimedOut };
	}
	// Federate across multiple collections when `collections` is set.
	// Falls back to single-collection mode for back-compat.
	const collections = opts.collections && opts.collections.length > 0
		? opts.collections
		: [opts.collection ?? process.env.DREAM_QMD_COLLECTION ?? DEFAULT_QMD_COLLECTION];
