	const timeoutMs = opts.timeoutMs ?? 4000;
	const deadlineMs = Date.now() + timeoutMs;
	const includeVec = opts.includeVec ?? true;
	const rerank = opts.rerank ?? true;
	// External rerank provider (TEI). When enabled and rerank requested, we
	// fetch a wider candidate pool from qmd with rerank disabled, then re-score
	// out-of-process. Falls through to the qmd-internal rerank path otherwise.
	const teiCfg = rerank ? resolveRerankProvider() : null;
	const qmdRerank = teiCfg ? false : rerank;
	const qmdLimit = teiCfg ? Math.max(n, teiCfg.candidates) : n;
	// Sanitize query for qmd daemon: hyphens can be parsed as DSL negation, and
	// raw newlines/control chars make current /query return HTTP 500. Collapsing
	// to one line is semantically equivalent for BM25/vec search and keeps
	// active-memory prior context safe.
	const safeQuery = normaliseQmdQuery(query);
