const recallStartedAt = now();

// Pre-fetch hits from qmd. qmd may be unhealthy; we federate candidates and
// let the selector choose permalinks from actual hits rather than bailing
// when hits.length === 0.
let qmdHits: SearchHit[] = [];
let qmdDegraded = false;
let isPrimaryLookupRoute = false;
let primaryLookupReason: RecallCollectionRoute["reason"] = "default-memory";
try {
	if (opts.searchFn) {
		qmdHits = await opts.searchFn(effectiveQuery, { topN: cfg.max_hits, cwd: opts.cwd });
	} else {
		const projectSlug = await resolveProjectSlug(opts.cwd ?? process.cwd()).catch(() => undefined);
		const qmdRoute = resolveActiveRecallRoute(effectiveQuery, projectSlug);
		isPrimaryLookupRoute = qmdRoute.reason === "workspace" || qmdRoute.reason === "project-docs";
		primaryLookupReason = qmdRoute.reason;
		const extras = buildActiveRecallExtraQueries(effectiveQuery);
		const baseSearchOpts = {
			timeoutMs: budgetMs,
			qmdMode: qmdRoute.qmdMode ?? cfg.qmd_mode,
			candidateLimit: cfg.candidate_limit,
			httpPort: isPrimaryLookupRoute ? 0 : cfg.qmd_http_port,
			...(qmdRoute.qmdMode === "search" ? { rerank: false } : {}),
			...(extras.length > 0 ? { extraQueries: extras } : {}),
		};
		const qmdSearch = isPrimaryLookupRoute ? searchMemoryQmd : searchMemory;
		const searchCollections = async (collections: string[], pageSize: number) => {
			const queries = [effectiveQuery, ...extras];
			const { extraQueries: _extraQueries, ...singleQueryOpts } = baseSearchOpts;
			const perQuery = await Promise.all(collections.flatMap((collection) =>
				queries.map((query) =>
					qmdSearch(query, {
						...singleQueryOpts,
						pageSize,
						collections: [collection],
					}),
				),
			));
			return {
				results: perQuery.flatMap((result) => result.results),
				timedOut: perQuery.some((result) => result.timedOut),
				error: perQuery.find((result) => result.error)?.error,
			};
		};
		const qmdPromise = qmdRoute.primaryCollections && qmdRoute.globalCollections
			? Promise.all([
				searchCollections(qmdRoute.primaryCollections, Math.max(3, Math.ceil(cfg.max_hits * 0.6))),
				searchCollections(qmdRoute.globalCollections, Math.max(2, Math.floor(cfg.max_hits * 0.4))),
			]).then(([primary, global]) => ({
				results: [...primary.results, ...global.results],
				timedOut: primary.timedOut || global.timedOut,
				error: primary.error ?? global.error,
			}))
			: qmdSearch(effectiveQuery, {
				...baseSearchOpts,
				pageSize: cfg.max_hits,
				collections: qmdRoute.collections,
			});
		const qmd = await qmdPromise.catch((err) => {
			log(`[active-recall] qmd query failed: ${(err as Error).message}`);
			return { results: [] as SearchHit[], timedOut: false, error: String(err) };
		});
		if (qmd.timedOut || qmd.error) {
			qmdDegraded = true;
			log(`[active-recall] qmd degraded: ${qmd.error ?? "timeout"}`);
		}
		qmdHits = qmd.results ?? [];
	}
} catch (err) {
	log(`[active-recall] pre-fetch failed: ${(err as Error).message}`);
	// Fall through with empty hits — still let the haiku decide.
}

