/**
 * Public recall entry. Dispatches by `DREAM_EMBED_MODE` (default `qmd`,
 * which preserves today's behavior byte-for-byte). When the env names a
 * non-default mode we either serve from the qmd-vector-sidecar instead of
 * qmd, log a sampled shadow comparison, or both. Sidecar errors degrade
 * the served arm to `results: []` rather than throwing.
 */
export async function searchMemory(
	query: string,
	opts: SearchOptions = {},
): Promise<SearchResult> {
	const mode = embedMode();

	// qmd or shadow: serve from qmd; in shadow mode optionally fire the
	// sidecar arm in the background and log the comparison.
	if (mode === "qmd" || mode === "shadow") {
		const t0 = Date.now();
		const served = await searchMemoryQmd(query, opts);
		if (mode === "shadow" && shouldFireShadow()) {
			fireShadowAndLog({
				mode: "shadow",
				servedArm: "qmd",
				servedResult: served,
				servedLatencyMs: Date.now() - t0,
				query,
				shadowFn: () => searchVectorSidecar(query, opts),
			});
		}
		return served;
	}

	// tei or shadow-tei: serve from sidecar; in shadow-tei mode optionally
	// fire the qmd arm in the background.
	const t0 = Date.now();
	const served = await searchVectorSidecar(query, opts);
	if (mode === "shadow-tei" && shouldFireShadow()) {
		fireShadowAndLog({
			mode: "shadow-tei",
			servedArm: "tei",
			servedResult: served,
			servedLatencyMs: Date.now() - t0,
			query,
			shadowFn: () => searchMemoryQmd(query, opts),
		});
	}
	return served;
}

